style.css:
@-moz-document domain("roblox.com") {
html, body {
    height: 100% !important;
  }

  body {
    background-color: #000000 !important; /* zapasowe tło */
    background-image: url("https://w.wallhaven.cc/full/5g/wallhaven-5g9qk7.png") !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: right center !important; /* dziewczyna po prawej */
    background-size: contain !important;          /* cała postać widoczna */
  }

  .rbx-body,
  .content,
  .container,
  #nav-roblox,
  #navigation-container,
  #Wrapper,
  .content-area,
  .section,
  .section-content {
    background: none !important;
    background-color: transparent !important;
  }
}
